    b=BASE/'trials'/arm;d=read(b/'POSTSEAL_RESULTS.json');assert read(b/'CPU_COMPLETION.json')['result_sha256']==sha(b/'POSTSEAL_RESULTS.json');s,p=aggregate(d['rows']);assert s==d['summary']and p==d['paired']and len(d['rows'])==96
